def longest_common_substring(a: str, b: str) -> int:
    """Length of the longest run of characters that appears contiguously in both strings."""
    m: int = len(b)
    prev: list[int] = []
    cur: list[int] = []
    for j in range(m + 1):
        prev.append(0)
        cur.append(0)
    best: int = 0
    for i in range(1, len(a) + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                cur[j] = prev[j - 1] + 1
                if cur[j] > best:
                    best = cur[j]
            else:
                cur[j] = 0
        for j in range(m + 1):
            prev[j] = cur[j]
    return best

